-- Ids are UUIDs generated by the client, so records created offline keep their id after sync.
-- created_at / updated_at come from the device; synced_at is set by the server.

CREATE TABLE person (
    id              CHAR(36)     PRIMARY KEY,
    full_name       VARCHAR(150) NOT NULL,
    birth_date      DATE         NULL,
    sex             VARCHAR(20)  NULL,
    document_number VARCHAR(20)  NULL,
    phone           VARCHAR(30)  NULL,
    email           VARCHAR(150) NULL,
    created_by      CHAR(36)     NOT NULL,
    created_at      DATETIME(3)  NOT NULL,
    updated_at      DATETIME(3)  NOT NULL,
    synced_at       DATETIME(3)  NOT NULL
);

-- One medical record (prontuario) per person.
CREATE TABLE medical_record (
    id                     CHAR(36)    PRIMARY KEY,
    person_id              CHAR(36)    NOT NULL UNIQUE,
    blood_type             VARCHAR(5)  NULL,
    allergies              TEXT        NULL,
    chronic_conditions     TEXT        NULL,
    continuous_medications TEXT        NULL,
    notes                  TEXT        NULL,
    created_by             CHAR(36)    NOT NULL,
    created_at             DATETIME(3) NOT NULL,
    updated_at             DATETIME(3) NOT NULL,
    synced_at              DATETIME(3) NOT NULL,
    CONSTRAINT fk_medical_record_person FOREIGN KEY (person_id) REFERENCES person (id)
);

-- Encounters (atendimentos) are append-only: a clinical event is never overwritten.
-- professional_name is copied from the token because professionals live in the identity service.
CREATE TABLE encounter (
    id                  CHAR(36)     PRIMARY KEY,
    medical_record_id   CHAR(36)     NOT NULL,
    professional_id     CHAR(36)     NOT NULL,
    professional_name   VARCHAR(150) NOT NULL,
    occurred_at         DATETIME(3)  NOT NULL,
    location            VARCHAR(255) NULL,
    chief_complaint     TEXT         NOT NULL,
    systolic_bp         INT          NULL,
    diastolic_bp        INT          NULL,
    heart_rate          INT          NULL,
    respiratory_rate    INT          NULL,
    oxygen_saturation   INT          NULL,
    temperature         DECIMAL(4,1) NULL,
    blood_glucose       INT          NULL,
    glasgow_eye         TINYINT      NOT NULL,
    glasgow_verbal      TINYINT      NOT NULL,
    glasgow_motor       TINYINT      NOT NULL,
    manchester_priority VARCHAR(10)  NOT NULL,
    start_category      VARCHAR(10)  NULL,
    procedures          TEXT         NULL,
    notes               TEXT         NULL,
    destination         VARCHAR(150) NULL,
    created_at          DATETIME(3)  NOT NULL,
    synced_at           DATETIME(3)  NOT NULL,
    CONSTRAINT fk_encounter_medical_record FOREIGN KEY (medical_record_id) REFERENCES medical_record (id),
    INDEX idx_encounter_occurred_at (occurred_at)
);

CREATE TABLE encounter_medication (
    id              CHAR(36)      PRIMARY KEY,
    encounter_id    CHAR(36)      NOT NULL,
    medication_id   CHAR(36)      NOT NULL,
    dose            DECIMAL(10,2) NOT NULL,
    route           VARCHAR(30)   NULL,
    administered_at DATETIME(3)   NOT NULL,
    CONSTRAINT fk_encounter_medication_encounter FOREIGN KEY (encounter_id) REFERENCES encounter (id),
    CONSTRAINT fk_encounter_medication_medication FOREIGN KEY (medication_id) REFERENCES medication (id)
);

-- Idempotency: every sync operation id is stored once, so a resent batch is not applied twice.
CREATE TABLE processed_operation (
    operation_id CHAR(36)    PRIMARY KEY,
    entity_type  VARCHAR(30) NOT NULL,
    entity_id    CHAR(36)    NOT NULL,
    outcome      VARCHAR(30) NOT NULL,
    processed_at DATETIME(3) NOT NULL
);

CREATE TABLE access_log (
    id              BIGINT       AUTO_INCREMENT PRIMARY KEY,
    occurred_at     DATETIME(3)  NOT NULL,
    client_ip       VARCHAR(45)  NOT NULL,
    professional_id CHAR(36)     NULL,
    method          VARCHAR(10)  NOT NULL,
    route           VARCHAR(255) NOT NULL,
    status_code     INT          NOT NULL,
    duration_ms     INT          NOT NULL,
    INDEX idx_access_log_occurred_at (occurred_at)
);
